`timescale 1ns/1ps
// Die-name calendar sequencers (Q-DVM+LINK 2026-10-15): one per link end, the compiler images as constants
// (d2d_cal_image.svh, generated by tools/qwen_split/d2d_cal_seq_image.py).  They produce the link end's cfg_* /
// cal_start / cal_seg inputs; their own inputs are the die's token start (tok_go, from the sequencer), the link end's
// epoch_abort (halt) and the HOST's exceptional image reload.  See ot_qwen_d2d_cal_seq.sv.
`include "d2d_cal_image.svh"
module qfd_d2d_cal_seq #(parameter integer GO_OFS = 0, parameter [20*36-1:0] START_ADJ = '0) (
    input wire ck, rst_n, reload, tok_go, halt,
    output wire cfg_tx_we, cfg_rx_we, output wire [5:0] cfg_addr, output wire [31:0] cfg_data,
    output wire cal_start, cal_seg, cal_ready, running, output wire [5:0] layer, output wire fault);
    ot_qwen_d2d_cal_seq #(.GO_OFS(GO_OFS), .TX_IMG(D2D_CAL_C_TX_IMG), .RX_IMG(D2D_CAL_C_RX_IMG),
        .TX_SEG1(D2D_CAL_C_TX_SEG1), .RX_SEG1(D2D_CAL_C_RX_SEG1), .START(D2D_CAL_START + START_ADJ)) u_seq (
        .ck(ck), .rst_n(rst_n), .reload(reload), .tok_go(tok_go), .halt(halt), .cfg_tx_we(cfg_tx_we), .cfg_rx_we(cfg_rx_we),
        .cfg_addr(cfg_addr), .cfg_data(cfg_data), .cal_start(cal_start), .cal_seg(cal_seg), .cal_ready(cal_ready),
        .running(running), .layer(layer), .fault(fault));
endmodule
module qkd_d2d_cal_seq #(parameter integer GO_OFS = 0, parameter [20*36-1:0] START_ADJ = '0) (
    input wire ck, rst_n, reload, tok_go, halt,
    output wire cfg_tx_we, cfg_rx_we, output wire [5:0] cfg_addr, output wire [31:0] cfg_data,
    output wire cal_start, cal_seg, cal_ready, running, output wire [5:0] layer, output wire fault);
    ot_qwen_d2d_cal_seq #(.GO_OFS(GO_OFS), .TX_IMG(D2D_CAL_K_TX_IMG), .RX_IMG(D2D_CAL_K_RX_IMG),
        .TX_SEG1(D2D_CAL_K_TX_SEG1), .RX_SEG1(D2D_CAL_K_RX_SEG1), .START(D2D_CAL_START + START_ADJ)) u_seq (
        .ck(ck), .rst_n(rst_n), .reload(reload), .tok_go(tok_go), .halt(halt), .cfg_tx_we(cfg_tx_we), .cfg_rx_we(cfg_rx_we),
        .cfg_addr(cfg_addr), .cfg_data(cfg_data), .cal_start(cal_start), .cal_seg(cal_seg), .cal_ready(cal_ready),
        .running(running), .layer(layer), .fault(fault));
endmodule
